import DOMPurify from "dompurify";

const RICH_TEXT_TAGS = [
  "p",
  "br",
  "strong",
  "em",
  "u",
  "s",
  "blockquote",
  "ol",
  "ul",
  "li",
  "h1",
  "h2",
  "h3",
  "pre",
  "code",
  "span",
  "a",
];

const RICH_TEXT_ATTRIBUTES = ["href", "target", "rel", "class"];

/**
 * Sanitizes the limited HTML generated by the rich-text notes editor.
 * Notes are loaded client-side, so returning an empty value during SSR avoids
 * ever rendering unsanitized database content on the server.
 */
export function sanitizeRichText(html: string): string {
  if (!html || typeof window === "undefined") return "";

  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: RICH_TEXT_TAGS,
    ALLOWED_ATTR: RICH_TEXT_ATTRIBUTES,
    ALLOW_DATA_ATTR: false,
    FORBID_TAGS: [
      "script",
      "style",
      "iframe",
      "object",
      "embed",
      "form",
      "input",
      "button",
      "svg",
      "math",
    ],
    FORBID_ATTR: ["style"],
  });
}

/**
 * Accepts only absolute HTTPS URLs. HTTP is allowed exclusively for localhost
 * during development so production data cannot create unsafe protocol links.
 */
export function safeExternalUrl(value: string | null | undefined): string | null {
  if (!value) return null;

  try {
    const url = new URL(value.trim());
    if (url.protocol === "https:") return url.toString();

    const isLocalDevelopment =
      import.meta.env.DEV &&
      url.protocol === "http:" &&
      (url.hostname === "localhost" || url.hostname === "127.0.0.1" || url.hostname === "::1");

    return isLocalDevelopment ? url.toString() : null;
  } catch {
    return null;
  }
}

/**
 * Prevents spreadsheet applications from interpreting exported user content
 * as formulas.
 */
export function safeCsvCell(value: unknown): string {
  const text = String(value ?? "");
  const neutralized = /^[=+\-@\t\r]/.test(text) ? `'${text}` : text;
  return `"${neutralized.replace(/"/g, '""')}"`;
}

export function isValidAttachmentPath(path: string): boolean {
  const parts = path.split("/");
  if (parts.length !== 3) return false;

  const [userId, folder, fileName] = parts;
  return (
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(userId) &&
    (folder === "leads" || folder === "tasks") &&
    /^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$/.test(fileName) &&
    !fileName.includes("..")
  );
}
